reference_solution:
def killed_processes(pid, ppid, kill):
    children = {}
    for child, parent in zip(pid, ppid):
        children.setdefault(parent, []).append(child)
    answer = []
    queue = [kill]
    for process in queue:
        answer.append(process)
        queue.extend(children.get(process, []))
    return answer

